import test from 'node:test';import assert from 'node:assert/strict';import {validateWebsiteData,visibleItems,localize} from '../../website-data.mjs';import {fixture} from './fixture.mjs';
test('website data is manual, island scoped and independent',()=>{const d=validateWebsiteData(fixture());assert.equal(visibleItems(d,{island:'AGATTI',kind:'SERVICE'}).length,1);assert.equal(visibleItems(d,{island:'AGATTI',kind:'PRODUCT'})[0].name,'Tuna pickle');assert.equal(localize(d.items[0].title,'ml'),'കയാക്കിംഗ്');});
test('inactive islands cannot publish active items',()=>{const d=fixture();d.items[0].islandCode='KAVARATTI';assert.throws(()=>validateWebsiteData(d),/ITEM_ISLAND_INACTIVE/);});
test('website rejects duplicate identity and unsafe images',()=>{let d=fixture();d.items.push(structuredClone(d.items[0]));assert.throws(()=>validateWebsiteData(d),/ITEM_DUPLICATE/);d=fixture();d.items[0].photos=[{src:'javascript:alert(1)',alt:{}}];assert.throws(()=>validateWebsiteData(d),/IMAGE_INVALID/);});
test('custom homepage/item blocks and manual reviews are preserved',()=>{const d=validateWebsiteData(fixture());assert.equal(d.homepageBlocks[0].title.en,'Plan your island day');assert.equal(d.items[0].blocks[0].style,'note');assert.equal(d.items[1].reviews[0].verified,true);});
test('travel packages remain disabled on public website',()=>{const d=fixture();d.items[0].category='Travel Packages';assert.throws(()=>validateWebsiteData(d),/TRAVEL_PACKAGE_DISABLED/);});
